import json, math, hashlib
from pathlib import Path
R=Path(__file__).resolve().parents[2]; OUT=R/'stereo-course/merzlyak-10-base/lessons'; SQ=math.sqrt
COVER=[]
def V(label,segments=None,polygon=None,points=None,poly=None,segs=None):
 polygon=polygon or poly;segments=segments or segs
 d={'label':label}
 for k,v in [('segments',segments),('polygon',polygon),('points',points)]:
  if v:d[k]=v
 return d
def model(p,e,faces=None,views=None,labels=None,planar=False):
 d={'points':{k:list(v) for k,v in p.items()},'edges':e,'views':{'neutral':V('Условие и вспомогательные точки'),**(views or {})},'labelNames':labels or [k for k in p if not k.startswith('_')]}
 if faces:d['faces']=faces
 if planar:d['planar']=True
 return d
def floor(p):
 z=[v for k,v in p.items() if not k.startswith('_')];q=max(1,max(max(abs(t) for t in v) for v in z));q*=1.1
 for k,v in zip(['_p0','_p1','_p2','_p3'],[[-q,-q,0],[q,-q,0],[q,q,0],[-q,q,0]]):p[k]=v
 return ['_p0','_p1','_p2','_p3']
def inc(top='M',foot='O',h=2,ends=None):
 ends=ends or {'A':(3,0),'B':(0,3)};p={foot:[0,0,0],top:[0,0,h],**{k:[*v,0] for k,v in ends.items()}}
 f=floor(p);e=[[top,foot]]+[[top,k] for k in ends]+[[foot,k] for k in ends]
 vs={'height':V('Перпендикуляр к плоскости',segments=[[top,foot]]),'base':V('Проекции в плоскости',segments=[[foot,k] for k in ends],polygon=f)}
 for k in ends:vs[k]=V('Прямоугольный треугольник '+top+foot+k,polygon=[top,foot,k])
 return model(p,e,[f],vs)
def tri(p,extra=None,faces=None):
 e=[['A','B'],['B','C'],['C','A']]+(extra or [])
 return model(p,e,faces or [['A','B','C']],{'base':V('Основание ABC',polygon=['A','B','C'])})
def box(x=2,y=2,z=2):
 p={'A':[0,0,0],'B':[x,0,0],'C':[x,y,0],'D':[0,y,0],'A1':[0,0,z],'B1':[x,0,z],'C1':[x,y,z],'D1':[0,y,z]}
 e=[[a,b] for a,b in [('A','B'),('B','C'),('C','D'),('D','A'),('A1','B1'),('B1','C1'),('C1','D1'),('D1','A1'),('A','A1'),('B','B1'),('C','C1'),('D','D1')]]
 return model(p,e,[['A','B','C','D'],['A1','B1','C1','D1']],{'base':V('Плоскость основания',polygon=['A','B','C','D'])})
def sq(side=2,h=2,top='M'):
 a=side/2;p={'A':[-a,-a,0],'B':[a,-a,0],'C':[a,a,0],'D':[-a,a,0],'O':[0,0,0],top:[0,0,h],'H':[0,-a,0]}
 return model(p,[['A','B'],['B','C'],['C','D'],['D','A'],[top,'O'],[top,'A'],[top,'B'],[top,'C'],[top,'D'],[top,'H'],['O','H']],[['A','B','C','D']],{'height':V('Высота к центру квадрата',segments=[[top,'O']]),'side':V('Расстояние до стороны',polygon=[top,'O','H']),'vertex':V('Наклонная к вершине',polygon=[top,'O','A'])})
def equi(side=6,h=2,top='M',foot='A'):
 p={'A':[0,0,0],'B':[side,0,0],'C':[side/2,side*SQ(3)/2,0],'O':[side/2,side*SQ(3)/6,0],'E':[3*side/4,side*SQ(3)/4,0]};p[top]=[p[foot][0],p[foot][1],h]
 return tri(p,[[top,foot],[top,'A'],[top,'B'],[top,'C'],['A','E'],[top,'E']])
def add(m,key,label,segs=None,poly=None,pts=None):m['views'][key]=V(label,segs,poly,pts);return m
def step(title,explanation,v='neutral',reason='Определение угла прямой с плоскостью; прямоугольный треугольник.'):
 return {'title':title,'prompt':title+': какой вывод следует из условия и почему?','explanation':explanation,'justifications':[{'kind':'theorem','text':reason}],'view':v}
def save(p,n,title,text,m,steps,hint,parts=None,issue=None,caption=None):
 page=(114 if n<=5 else 115 if n<=13 else 116 if n<=23 else 117) if p==12 else (122 if n<=3 else 123 if n<=9 else 124 if n<=15 else 125 if n<=25 else 126 if n<=37 else 127)
 pages=[page]+([page+1] if (p,n) in [(12,1),(13,2)] else [])
 d={'schemaVersion':1,'revision':1,'id':f'ex-{p:02}-{n:03}','kind':'exercise','title':f'№ {p}.{n}. {title}','status':'draft','source':{'bookId':'merzlyak-2022-10-base','collection':'main','exercise':f'{p}.{n}','chapter':'Глава 3. Перпендикулярность в пространстве','printedPages':pages,'pdfPages':[x+1 for x in pages]},'statement':{'text':text,'goal':'Реши все указанные пункты и объясни выбор вспомогательной фигуры.'},'visualization':{'type':'scene3d','caption':caption or 'Индивидуальная модель задачи. Сначала найди перпендикуляр и нужную проекцию или линейный угол; размеры по экрану не измеряют. Плоскости продолжаются за пределы показанных фрагментов.','model':m},'help':[{'id':'help-1','question':'С чего начать?','text':hint}],'steps':[dict(s,id=f'step-{i+1}') for i,s in enumerate(steps)],'answer':{'mode':'manual','prompt':'Запиши ответ по каждому пункту с единицами и обоснованием. Запись сохраняется для обсуждения с преподавателем; доказательство автоматически не оценивается.'},'review':{'source':'pending','mathematics':'pending','pedagogy':'pending'}}
 path=OUT/f'ex-{p:02}-{n:03}.json';path.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
 COVER.append({'sourceId':f'source-main-{p:02}-{n:03}','exercise':f'{p}.{n}','printedPages':pages,'pdfPages':[x+1 for x in pages],'requiredParts':[None],'sourceSubparts':parts or ['всё условие'],'coveredBy':[d['id']],'file':str(path.relative_to(R)),'sha256':hashlib.sha256(path.read_bytes()).hexdigest(),'sourceIssue':issue,'coverage':'draft solution of all literal cases' if not issue else 'draft analysis; source clarification remains pending'})

