m=box();m['points']['O']=[1,1,0]
for k,poly in [('one',['A','A1','B1']),('two',['A','C','C1']),('three',['A','D','C1']),('four',['A1','A','O']),('five',['C','D','A'])]:add(m,k,'Наклонная и её ортогональная проекция',poly=poly)
save(12,1,'Углы в кубе','Дан куб ABCDA₁B₁C₁D₁; O — центр грани ABCD. Укажи угол между: 1) AB₁ и A₁B₁C₁; 2) AC₁ и ABC; 3) AC₁ и CDD₁; 4) OA₁ и ABC; 5) AC и ADD₁.',m,[step('1. Верхняя грань','Проекция A на верхнюю грань — A₁, B₁ уже в ней. Искомый угол — ∠AB₁A₁.','one'),step('2. Нижняя грань','Проекция C₁ — C. Поэтому проекция AC₁ — AC, угол — ∠C₁AC.','two'),step('3. Задняя грань','AD перпендикулярна плоскости CDD₁; проекция A — D. Угол — ∠AC₁D.','three'),step('4. Диагональ к центру','Проекция A₁ — A, O находится в основании. Угол — ∠A₁OA.','four'),step('5. Боковая грань','CD перпендикулярна ADD₁. Проекция AC — AD, угол — ∠CAD.','five')],'Проецируй каждый конец отрезка на указанную плоскость.',parts=['1','2','3','4','5'])
