m=inc(foot='A',h=6,ends={'B':(6,0),'C':(0,2*SQ(3))})
save(12,6,'Две наклонные к основанию','MA⊥(ABC), AB=AM=6см, AC=2√3см. Найди угол с плоскостью ABC: 1) MB; 2) MC.',m,[step('1. Наклонная MB','Её проекция — AB. tan∠MBA=MA/AB=1, поэтому угол45°.','B'),step('2. Наклонная MC','Её проекция — AC. tan∠MCA=6/(2√3)=√3, поэтому угол60°.','C')],'У обоих прямоугольных треугольников общий катет MA.',parts=['1','2'])
