# §13: normal sections are constructed for each particular source condition.
def wedge(theta,r=3):
 t=math.radians(theta);c,s=math.cos(t),math.sin(t)
 p={'O':[0,0,0],'A':[0,r*c,r*s],'H':[0,r*c,0],'L':[-r/2,0,0],'R':[r/2,0,0],'_a':[-r/2,r*1.2,0],'_b':[r/2,r*1.2,0],'_c':[-r/2,r*1.2*c,r*1.2*s],'_d':[r/2,r*1.2*c,r*1.2*s]}
 return model(p,[['L','R'],['O','A'],['A','H'],['H','O']],[['L','R','_b','_a'],['L','R','_d','_c']],{'section':V('Сечение перпендикулярно ребру',poly=['O','H','A'])},labels=['O','A','H','L','R'])
def pair_wedge(theta,r,s,delta=0,names=('A','B','O','P')):
 a,b,o,q=names;m=wedge(theta,max(r,s));m['points'].update({o:[0,0,0],q:[delta,0,0],a:[0,r,0],b:[delta,s*math.cos(math.radians(theta)),s*math.sin(math.radians(theta))]})
 m['views'].pop('section');m['edges']=[[a,o],[b,q],[a,b],['L','R']];m['labelNames']=list(dict.fromkeys([a,b,o,q,'L','R']));add(m,'cross','Две поперечные составляющие',segs=[[a,o],[b,q],[a,b]])
 return m
