save(13,34,'Угол при сдвиге вдоль ребра','ИзA,B на разных гранях опущеныAC,BD на ребро двугранного угла. AC=CD=BD=2см,AB=2√2см. Найди угол.',m,[step('Нормальный перенос','ПеренесиB вдоль ребра доB′ так, чтобы основанием сталоC. BB′=CD=2. ИзAB²=AB′²+BB′² получаемAB′²=8−4=4.','length','Теорема Пифагора.'),step('Равностороннее сечение','CA=CB′=AB′=2. ТреугольникACB′ равносторонний, его угол приC равен60° — искомый двугранный угол.','normal','Определение линейного угла.')],'После переноса получится треугольник с тремя равными сторонами.')
m=pair_wedge(30,3,4*SQ(3),2,('C','D','E','F'));m['points']['Dp']=[0,*m['points']['D'][1:]];m['labels']={'Dp':'D′'};add(m,'transfer','Перенос D вдоль ребра',segs=[['D','Dp'],['E','Dp'],['C','Dp']],pts=['Dp']);add(m,'normal','Нормальный треугольник CED′',poly=['C','E','Dp']);m['points']['C2']=[0,9,0];m['edges'] += [['E','C2'],['C2','D']];m['labelNames']=['C','C2','D','E','F'];add(m,'alternative','Второе положение C₂',segs=[['E','C2'],['C2','D'],['D','F']])
save(13,35,'Два допустимых расстояния до ребра','C,D лежат на разных гранях двугранного угла30°, CE,DF перпендикулярны ребру. CD=5см,DF=4√3см,EF=2см. НайдиCE.',m,[step('Удалим продольный сдвиг','ПеренесиD вдоль ребра в нормальную плоскость черезE, получивD′. ТогдаCD′²=CD²−EF²=25−4=21, ED′=4√3.','transfer','Теорема Пифагора.'),step('Квадратное уравнение','ПустьCE=x>0. По косинусам21=x²+48−2·x·4√3cos30°=x²+48−12x. Значитx²−12x+27=0.','normal','Теорема косинусов.'),step('Оба корня допустимы','(x−3)(x−9)=0, поэтомуCE=3см или9см. Оба положительных значения дают расстояниеCD=5; модель показывает C и альтернативное C₂.','alternative','Проверка корней в исходном условии.')],'Не отбрасывай один корень без геометрической причины.')
